function shoppingUnit(category,item){const text=`${category||''} ${item||''}`.toLowerCase();if(/milk|juice|water|soda|beverage|detergent|cleaner|oil/.test(text))return 'gallon';if(/beef|chicken|steak|bacon|fish|meat|seafood|cheese/.test(text))return 'pound';if(/egg/.test(text))return 'dozen';if(/bread|bagel|tortilla|paper towel|toilet paper|napkin|tissue|diaper|wipe|trash bag|sponge/.test(text))return 'package';if(/apple|banana|avocado|tomato|berry|produce|snack|chip|cracker|nut|bar/.test(text))return 'individual';return 'individual';}
function shoppingForm(propertyId){const categoryOptions='<option value="">Choose a category</option>'+shoppingCategories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');const fields=select('category','1. Category',categoryOptions)+'<div id="shoppingItemSlot"></div><div id="shoppingVariantSlot"></div><div id="shoppingBrandSlot"></div>'+input('quantity','Quantity','number','1')+select('quantityUnit','Unit',shoppingUnitOptions('individual'))+textarea('notes','Preferences or placement');dialog('Add preferred item',fields,'Save',async(b)=>{if(!b.category)throw Error('Choose a category first.');const baseItem=b.itemChoice==='Other'?b.customItem:b.itemChoice;const variant=b.variantChoice==='Other'?b.customVariant:b.variantChoice;const item=[baseItem,variant&&variant!=='Other'?variant:''].filter(Boolean).join(' - ');const brand=b.brandChoice==='Other'?b.customBrand:b.brandChoice;if(!item?.trim())throw Error('Choose an item or enter a custom item.');if(!brand?.trim())throw Error('Choose a brand or enter a custom brand.');const notes=[brand?`Brand: ${brand}`:'',b.notes].filter(Boolean).join('\n');await api('shopping',{propertyId,name:item.trim(),quantity:`${b.quantity||1} ${b.quantityUnit||'individual'}`,category:b.category||'Other',notes});});const updateBrands=()=>{const category=$('f-category').value,item=$('f-itemChoice').value,variant=$('f-variantChoice')?.value;const items=shoppingCatalog[category]||{'Other':['Other']};const brands=[...(items[item]||['Other']),...(retailerBrands[category]||[])].filter((b,i,a)=>a.indexOf(b)===i);$('shoppingBrandSlot').innerHTML=select('brandChoice','4. Brand','<option value="">Choose a brand</option>'+brands.map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join(''))+'<div id="shoppingCustomBrand"></div>';$('f-brandChoice').onchange=()=>{$('shoppingCustomBrand').innerHTML=$('f-brandChoice').value==='Other'?input('customBrand','Custom brand'):'';};const labelItem=[item,variant&&variant!=='Other'?variant:''].filter(Boolean).join(' ');if($('f-quantityUnit'))$('f-quantityUnit').value=shoppingUnit(category,labelItem);};const update=()=>{const category=$('f-category').value;const items=shoppingCatalog[category]||{'Other':['Other']};const itemOptions='<option value="">Choose an item</option>'+Object.keys(items).map(item=>`<option value="${esc(item)}">${esc(item)}</option>`).join('');$('shoppingItemSlot').innerHTML=select('itemChoice','2. Item',itemOptions)+'<div id="shoppingCustomItem"></div>';const item=$('f-itemChoice');const variants=shoppingVariants[category]?.[item.value];$('shoppingVariantSlot').innerHTML=variants?select('variantChoice','3. Type',variants.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join(''))+'<div id="shoppingCustomVariant"></div>':'';if(variants){$('f-variantChoice').onchange=()=>{$('shoppingCustomVariant').innerHTML=$('f-variantChoice').value==='Other'?input('customVariant','Custom type'):'';updateBrands();};}$('shoppingBrandSlot').innerHTML='';item.onchange=()=>{$('shoppingCustomItem').innerHTML=item.value==='Other'?input('customItem','Custom item name'):'';const next=shoppingVariants[category]?.[item.value];$('shoppingVariantSlot').innerHTML=next?select('variantChoice','3. Type',next.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join(''))+'<div id="shoppingCustomVariant"></div>':'';if(next){$('f-variantChoice').onchange=()=>{$('shoppingCustomVariant').innerHTML=$('f-variantChoice').value==='Other'?input('customVariant','Custom type'):'';updateBrands();};}$('shoppingBrandSlot').innerHTML='';updateBrands();};if(item.value)updateBrands();};$('f-category').onchange=update;update();}

const option=(rows,value='id',name='name',selected='')=>rows.map(r=>`<option value="${esc(r[value])}" ${r[value]===selected?'selected':''}>${esc(r[name])}</option>`).join('');
const input=(name,title,type='text',value='',required=true)=>`<div class="field"><label for="f-${name}">${esc(title)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="0.01" min="0.01"':''} ${type==='password'?'minlength="12" autocomplete="new-password"':''}></div>`;
const select=(name,title,options)=>`<div class="field"><label for="f-${name}">${esc(title)}</label><select id="f-${name}" name="${name}">${options}</select></div>`;
const textarea=(name,title,value='')=>`<div class="field full"><label for="f-${name}">${esc(title)}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;
const roomTypes=[['living-room','Living room'],['family-room','Family room'],['dining-room','Dining room'],['kitchen','Kitchen'],['office','Office'],['laundry-room','Laundry room'],['garage','Garage'],['patio','Patio / outdoor area'],['pool-house','Pool house'],['guest-house','Guest house']];
const clientRoomProfile=p=>{try{return typeof p.room_profile==='string'?JSON.parse(p.room_profile||'{}'):(p.room_profile||{});}catch{return {};}};
const roomCount=(name,title,value=0)=>`<div class="field"><label for="f-${name}">${esc(title)}</label><input id="f-${name}" name="${name}" type="number" min="0" step="1" value="${esc(value)}"></div>`;
const roomProfileForm=(p={})=>{const r=clientRoomProfile(p),selected=new Set((r.rooms||[]).map(x=>x.key));return `<fieldset class="room-profile"><legend>Residence rooms and spaces</legend><p class="muted">These rooms become check-in readiness tasks.</p>${roomCount('bedrooms','Bedrooms',r.bedrooms||0)}${roomCount('fullBathrooms','Full bathrooms',r.fullBathrooms||0)}${roomCount('halfBathrooms','Half bathrooms',r.halfBathrooms||0)}<div class="room-checks">${roomTypes.map(([key,name])=>`<label class="check-row"><input type="checkbox" name="roomKey" value="${key}" ${selected.has(key)?'checked':''}><span>${name}</span></label>`).join('')}</div><input type="hidden" name="roomProfile" id="f-roomProfile"></fieldset>`;};
function syncRoomProfile(){const rooms=[];const bedrooms=Math.max(0,Number($('f-bedrooms')?.value||0));const fullBathrooms=Math.max(0,Number($('f-fullBathrooms')?.value||0));const halfBathrooms=Math.max(0,Number($('f-halfBathrooms')?.value||0));for(let n=1;n<=bedrooms;n++)rooms.push({key:`bedroom-${n}`,name:`Bedroom ${n}`});for(let n=1;n<=fullBathrooms;n++)rooms.push({key:`full-bathroom-${n}`,name:`Full bathroom ${n}`});for(let n=1;n<=halfBathrooms;n++)rooms.push({key:`half-bathroom-${n}`,name:`Half bathroom ${n}`});document.querySelectorAll('[name=roomKey]:checked').forEach(el=>rooms.push({key:el.value,name:roomTypes.find(r=>r[0]===el.value)?.[1]||el.value}));if($('f-roomProfile'))$('f-roomProfile').value=JSON.stringify({bedrooms,fullBathrooms,halfBathrooms,rooms});}
const addressForm=(p={})=>`<fieldset class="address-fields"><legend>Property address</legend><div class="field full"><label for="f-addressSearch">Find address</label><input id="f-addressSearch" autocomplete="street-address" placeholder="Start typing an address"><div id="addressSuggestions" class="address-suggestions"></div></div>${p.address&&!p.street_address?`<p class="muted address-previous">Previously saved address: ${esc(p.address)}</p>`:''}<div class="field full"><label for="f-streetAddress">Street address</label><input id="f-streetAddress" name="streetAddress" autocomplete="address-line1" placeholder="123 Ocean Drive" value="${esc(p.street_address||'')}" required></div><div class="field full"><label for="f-addressLine2">Apartment, suite or unit <span class="muted">(optional)</span></label><input id="f-addressLine2" name="addressLine2" autocomplete="address-line2" placeholder="Unit 4B" value="${esc(p.address_line2||'')}"></div><div class="field"><label for="f-city">City</label><input id="f-city" name="city" autocomplete="address-level2" value="${esc(p.city||'')}" required></div><div class="field"><label for="f-state">State / province</label><input id="f-state" name="state" autocomplete="address-level1" placeholder="FL" value="${esc(p.state||'')}" required></div><div class="field"><label for="f-postalCode">ZIP / postal code</label><input id="f-postalCode" name="postalCode" autocomplete="postal-code" placeholder="33480" value="${esc(p.postal_code||'')}" required></div><div class="field"><label for="f-country">Country</label><input id="f-country" name="country" autocomplete="country-name" value="${esc(p.country||'United States')}" required></div></fieldset>`;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,5000);}
async function api(path,payload){const response=await fetch('/api/'+path,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed.');return result;}
async function load(){data=await api('data');render();}
function dialog(title,fields,submit,onSubmit){$('modalBody').innerHTML=`<h2>${esc(title)}</h2><div id="formError" class="error" hidden></div><form id="actionForm" class="form">${fields}<div class="dialog-footer">${btn('Cancel','close')}<button class="primary" type="submit">${esc(submit)}</button></div></form>`;$('actionForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const values=Object.fromEntries(new FormData(e.target));await onSubmit(values,e.target);$('modal').close();await load();}catch(error){$('formError').hidden=false;$('formError').textContent=error.message;}finally{button.disabled=false;}};$('modal').showModal();}
function auth(configured,invitation){let loginMode=configured&&!invitation;const draw=()=>{$('app').innerHTML=`<div class="auth"><section class="auth-intro"><div class="brand"><span>E</span>EstateOS</div><h1>Your residences.<br>Your team.<br>One place.</h1><p>Manage property care, prepare for arrivals, and keep every service and inspection connected to the right residence.</p></section><section class="auth-form"><div><div class="eyebrow">${invitation?'Your invitation':loginMode?'Welcome back':'Company setup'}</div><h2>${invitation?'Create your account':loginMode?'Sign in to EstateOS':'Set up your company'}</h2><p class="muted">${loginMode?'Use the email and password for your account.':invitation?'Choose your name and a password for your individual account.':'Create the first administrator account. Your workspace starts empty, ready for your real records.'}</p><div id="authError" class="error" hidden></div><form id="authForm">${!loginMode&&!invitation?input('company','Company name')+input('setupKey','Setup key from Render','password','',false):''}${!loginMode||invitation?input('name','Your name'):''}${!invitation?input('email','Email','email'):''}${input('password','Password','password')}<button class="primary" type="submit">${invitation?'Accept invitation':loginMode?'Sign in':'Create company'}</button></form>${!invitation?`<p class="footer-note">${loginMode?'Need to create the first workspace? ': 'Already have an account? '}<button type="button" class="link-button" data-auth-mode="${loginMode?'setup':'login'}">${loginMode?'Set up a new company':'Log in to an existing account'}</button></p>`:`<p class="footer-note">Use a password with at least 12 characters. This invitation expires after 48 hours.</p>`}</div></section></div>`;$('authForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const payload=Object.fromEntries(new FormData(e.target));if(invitation)payload.token=invitation;await api(invitation?'accept-invite':loginMode?'login':'setup',payload);history.replaceState(null,'','/');await load();}catch(error){$('authError').textContent=error.message;$('authError').hidden=false;}finally{e.submitter.disabled=false;}};const modeButton=document.querySelector('[data-auth-mode]');if(modeButton)modeButton.onclick=()=>{loginMode=modeButton.dataset.authMode==='login';draw();};};draw();}
function render(){const role=data.user.role;let nav=[['dashboard','Overview'],['properties',role==='client'?'My residences':'Residences'],['work',role==='vendor'?'My jobs':'Work orders']];if(role==='client')nav.push(['shopping','Shopping list']);if(role!=='vendor')nav.push(['inspections','Inspection reports'],['requests','Service requests'],['arrivals','Arrival preparation'],['calendar','Calendar'],['documents','Documents']);if(isStaff())nav.push(['maintenance','Maintenance'],['assets','Assets'],['routes','Daily route']);if(role==='admin')nav.push(['clients','Client families'],['vendors','Vendors'],['billing','Billing'],['users','Team & access'],['audit','Audit history']);nav.push(['notifications','Notifications']);if(!nav.some(n=>n[0]===page)&&page!=='property'&&page!=='inspection')page='dashboard';$('app').innerHTML=`<div class="shell"><aside id="sidebar"><div class="brand"><span>E</span>EstateOS</div><nav>${nav.map(([id,title])=>`<button data-action="navigate" data-id="${id}" class="${page===id?'active':''}">${title}${id==='notifications'&&data.notifications.some(n=>!n.read_at)?' •':''}</button>`).join('')}</nav><div class="identity">${esc(data.user.name)}<small>${esc(label(role))}</small>${btn('Sign out','logout')}</div></aside><main><header class="topbar">${btn('Menu','menu')}<input id="search" aria-label="Search current view" placeholder="Search residences, work and records…" value="${esc(search)}"><span class="company">${esc(data.company)}</span></header><div class="content" id="content">${view()}</div></main></div>`;$('search').addEventListener('input',e=>{search=e.target.value;$('content').innerHTML=view();});}
function filtered(rows){const q=search.toLowerCase();return rows.filter(r=>!q||Object.values(r).some(v=>typeof v==='string'&&v.toLowerCase().includes(q)));}
function head(title,subtitle='',action=''){return `<div class="head"><div><div class="eyebrow">${esc(data.company)}</div><h1>${esc(title)}</h1>${subtitle?`<div class="muted">${esc(subtitle)}</div>`:''}</div>${action}</div>`;}
function view(){
 if(page==='clients'&&activeClient&&data.user.role==='admin'){const c=data.clients.find(c=>c.id===activeClient);if(c)return clientView(c);}

 if(page==='property')return residenceView();if(page==='inspection')return inspectionView();
 if(page==='dashboard'){const open=data.work.filter(j=>j.status!=='completed');return head('Your estate overview','Property care, upcoming visits and recent updates.',data.user.role==='client'?btn('Plan my arrival','new-arrival','',true):'')+`<div class="stats">${[['Residences',data.properties.length,'properties'],['Open work',open.length,'work'],['Published reports',data.inspections.filter(i=>i.status==='published').length,'inspections'],['Upcoming arrivals',data.arrivals.filter(a=>!['completed','cancelled'].includes(a.status)).length,'arrivals'],['Submitted arrivals',data.arrivals.filter(a=>['submitted','preparing'].includes(a.status)).length,'arrivals']].map(([title,num,target])=>`<button class="stat stat-link" data-action="navigate" data-id="${target}" type="button"><div class="eyebrow">${title}</div><b>${num}</b><span class="muted">View details →</span></button>`).join('')}</div>${!data.properties.length?`<div class="panel"><h2>${data.user.role==='admin'?'Begin with a client family':'Your workspace is ready'}</h2><p class="muted">${data.user.role==='admin'?'Add a family, then their residence. Invite your team and clients when their records are ready.':'Your administrator will assign residences or jobs to your account.'}</p>${data.user.role==='admin'?btn('Add client family','new-client','',true):''}</div>`:''}<div class="two"><div class="panel"><h3>Work needing attention</h3>${workRows(open.slice(0,6))}</div><div class="panel"><h3>Inspection reports</h3>${inspectionRows(data.inspections.filter(i=>i.status==='published').slice(0,5))}</div></div>`;}
 if(page==='shopping')return head('Shopping list','Preferred items across your residences.')+data.properties.map(p=>`<div class="panel summary"><div class="head"><div><h2>${esc(p.name)}</h2><div class="muted">${esc(p.address||'Address not entered')}</div></div><div class="actions">${btn('Add item','new-shopping',p.id,true)}${btn('Plan arrival','new-arrival',p.id)}</div></div>${data.shopping.filter(i=>i.property_id===p.id).map(i=>`<div class="row"><div><strong>${esc(i.name)}</strong><div class="muted">${esc(i.category||'Other')} · ${esc(i.notes||'')}</div></div><b>${esc(i.quantity)}</b></div>`).join('')||empty('No preferred items saved for this residence yet.')}</div>`).join('')||empty('No residences are assigned to your account.');
 if(page==='properties')return head(data.user.role==='client'?'Your residences':'Residences','Each home, its records and its next visit.',data.user.role==='admin'?btn('Add residence','new-property','',true):'')+`<div class="grid">${filtered(data.properties).map(p=>`<article class="residence"><div class="residence-top"><div class="eyebrow">${esc(p.client_name||'Assigned residence')}</div><h2>${esc(p.name)}</h2></div><div class="residence-body"><p class="muted">${esc(p.address||'Address not entered')}</p><div class="actions">${btn('View residence','property',p.id,true)}${data.user.role==='admin'?btn('Edit profile','edit-property',p.id):''}${data.user.role==='client'?btn('Plan arrival','new-arrival',p.id,true)+btn('Request service','new-request',p.id):''}</div></div></article>`).join('')}</div>`+(!data.properties.length?empty('No residences assigned yet.'):'' )+(data.user.role==='admin'&&data.archivedProperties?.length?`<div class="panel summary"><h2>Archived residences</h2><p class="muted">Archived records are preserved and can be restored here.</p>${data.archivedProperties.map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><div class="muted">${esc(p.client_name||'')} · Archived ${esc(p.archived_at?.slice(0,10)||'')}</div></div>${btn('Restore residence','restore-property',p.id)}</div>`).join('')}</div>`:'');
 if(page==='clients')return head('Client families','Families and their residences.',btn('Add family','new-client','',true))+`<div class="panel">${filtered(data.clients).map(c=>`<div class="row"><div><strong>${esc(c.name)}</strong><div class="muted">${esc(c.email)} ${esc(c.phone)}</div></div><div class="actions">${badge(data.properties.filter(p=>p.client_id===c.id).length+' residences')}${btn('View family','client-open',c.id)}</div></div>`).join('')||empty('Add your first client family.')}</div>`;
 if(page==='vendors')return head('Vendor network','Create the vendor company, then invite its users.',btn('Add vendor','new-vendor','',true))+`<div class="panel">${filtered(data.vendors).map(v=>`<div class="row"><div><strong>${esc(v.name)}</strong><div class="muted">${esc(v.trade)} · ${esc(v.email)} · ${esc(v.phone)}</div></div></div>`).join('')||empty('No vendors yet.')}</div>`;
 if(page==='work')return head(data.user.role==='vendor'?'Your assigned jobs':'Work orders','Track work from assignment through verified completion.',isStaff()?btn('New work order','new-work','',true):'')+`<div class="panel">${workRows(filtered(data.work))}</div>`;
 if(page==='inspections')return head('Inspection reports','Published reports are shared with the correct family.',isStaff()?btn('Start inspection','new-inspection','',true):'')+`<div class="panel">${inspectionRows(filtered(data.inspections))}</div>`;
 if(page==='requests')return head('Service requests','Track requests and their assigned work.',btn('Request service','new-request','',true))+`<div class="panel">${filtered(data.requests).map(r=>`<div class="row"><div><strong>${esc(r.title)}</strong><div class="muted">${esc(propertyName(r.property_id))}</div><p>${esc(r.description)}</p>${isStaff()&&r.status!=='completed'?btn('Link work order','link-request',r.id):''}</div>${badge(r.status)}</div>`).join('')||empty('No service requests yet.')}</div>`;
 if(page==='arrivals'){const pending=data.arrivals.filter(a=>!['ready','completed','cancelled'].includes(a.status)),ready=data.arrivals.filter(a=>['ready','completed'].includes(a.status));if(activeArrival){const a=data.arrivals.find(a=>a.id===activeArrival);if(a)return arrivalDetail(a);}const rows=arrivalFilter==='ready'?ready:pending;return head('Arrival preparation','Review submitted arrivals, shopping, rooms and notes.',btn('Plan arrival','new-arrival','',true))+`<div class="tabs"><button data-action="arrival-filter" data-id="pending" class="${arrivalFilter==='pending'?'active':''}">Needs confirmation (${pending.length})</button><button data-action="arrival-filter" data-id="ready" class="${arrivalFilter==='ready'?'active':''}">Ready (${ready.length})</button></div>`+arrivalCards(rows);}
 if(page==='maintenance')return head('Preventive maintenance','Generate each due visit once from its schedule.',`<div class="actions">${btn('Run due schedules','run-maintenance','',true)}${btn('Add schedule','new-maintenance')}</div>`)+`<div class="panel">${filtered(data.maintenance).map(m=>`<div class="row"><div><strong>${esc(m.title)}</strong><div class="muted">${esc(propertyName(m.property_id))} · ${esc(m.frequency)} · Due ${esc(m.next_due)}</div></div>${btn('Create due work','generate-maintenance',m.id)}</div>`).join('')||empty('No maintenance schedules yet.')}</div>`;
 if(page==='assets')return head('Assets & equipment','Equipment identity, warranty details and service history.',btn('Add asset','new-asset','',true))+assetRows(filtered(data.assets));
 if(page==='documents')return head('Documents','Uploaded files stay attached to their residence.',isStaff()?btn('Upload document','new-document','',true):'')+`<div class="panel">${fileRows(filtered(data.files.filter(f=>!f.inspection_id&&!f.work_order_id)))}</div>`;
 if(page==='calendar'){const events=[...data.work.filter(w=>w.due_date).map(w=>({title:w.title,date:w.due_date,property_id:w.property_id,status:w.status})),...data.arrivals.map(a=>({title:'Arrival preparation',date:a.arrival_at,property_id:a.property_id,status:a.status})),...data.inspections.map(i=>({title:'Property inspection',date:i.inspection_date,property_id:i.property_id,status:i.status}))].sort((a,b)=>a.date.localeCompare(b.date));return head('Calendar','Scheduled work, inspections and arrivals.')+`<div class="panel">${events.map(e=>`<div class="row"><div><strong>${esc(e.title)}</strong><div class="muted">${esc(propertyName(e.property_id))} · ${esc(e.date.replace('T',' '))}</div></div>${badge(e.status)}</div>`).join('')||empty('No scheduled events yet.')}</div>`;}
 if(page==='billing')return billingView();if(page==='users')return usersView();
 if(page==='audit')return head('Audit history','Recorded account and operational changes.')+`<div class="panel">${data.audit.map(a=>`<div class="row"><div><strong>${esc(label(a.action.replaceAll('.',' ')))}</strong><div class="muted">${esc(a.actor_name)} · ${esc(new Date(a.created_at).toLocaleString())}</div></div></div>`).join('')||empty('No activity recorded.')}</div>`;
 if(page==='notifications')return head('Notifications')+`<div class="panel">${data.notifications.map(n=>`<div class="row"><div><strong>${esc(n.title)}</strong><div class="muted">${esc(new Date(n.created_at).toLocaleString())}</div></div>${!n.read_at?btn('Mark read','read-notification',n.id):badge('read')}</div>`).join('')||empty('You are up to date.')}</div>`;
 if(page==='routes')return routeView();return '';
}
function workRows(rows){return rows.map(w=>`<div class="row"><div><strong>${esc(w.title)}</strong><div class="muted">${esc(propertyName(w.property_id))}${w.due_date?' · Due '+esc(w.due_date):''}</div>${w.description?`<p class="pre">${esc(w.description)}</p>`:''}${w.service_notes?`<p class="pre">${esc(w.service_notes)}</p>`:''}<div class="actions">${['open','scheduled'].includes(w.status)&&data.user.role!=='client'?btn('Start work','work-start',w.id):''}${['open','scheduled','in_progress'].includes(w.status)&&data.user.role!=='client'?btn('Add photo','work-photo',w.id)+btn('Submit completion','work-submit',w.id):''}${w.status==='submitted'&&isStaff()?btn('Accept completion','work-accept',w.id,true)+btn('Return to vendor','work-return',w.id):''}${data.files.filter(f=>f.work_order_id===w.id).map(f=>`<a class="button" href="/api/files/${f.id}" target="_blank" rel="noopener">View photo</a>`).join('')}</div></div>${badge(w.status)}</div>`).join('')||empty('No work orders in this view.');}
function inspectionRows(rows){return rows.map(i=>`<div class="row"><div><strong>${esc(propertyName(i.property_id))}</strong><div class="muted">${esc(i.inspection_date)} · ${data.files.filter(f=>f.inspection_id===i.id).length} photos</div></div><div class="actions">${badge(i.status)}${btn(i.status==='draft'?'Continue':'View report','inspection',i.id)}${i.status==='published'?`<a class="button" href="/api/inspections/${i.id}/pdf">Download PDF</a>`:''}</div></div>`).join('')||empty('No inspection reports yet.');}
function fileRows(rows){return rows.map(f=>`<div class="row"><div><strong>${esc(f.name)}</strong><div class="muted">${esc(propertyName(f.property_id))} · ${Math.ceil(f.bytes/1024)} KB</div></div><a class="button" href="/api/files/${f.id}" target="_blank" rel="noopener">Open</a></div>`).join('')||empty('No files uploaded.');}
function assetRows(rows){return `<div class="grid">${rows.map(a=>`<div class="card"><div class="eyebrow">${esc(a.category)}</div><h2>${esc(a.name)}</h2><p class="muted">${esc(propertyName(a.property_id))} · ${esc(a.location)}</p><p>Model: ${esc(a.model||'Not recorded')}<br>Serial: ${esc(a.serial||'Not recorded')}<br>Warranty: ${esc(a.warranty||'Not recorded')}</p>${isStaff()?btn('Create work order','asset-work',a.id):''}<h3 class="summary">Service history</h3>${data.work.filter(w=>w.asset_id===a.id&&w.status==='completed').map(w=>`<div class="row"><div><strong>${esc(w.title)}</strong><div class="muted">${esc(w.service_notes)}</div></div></div>`).join('')||'<p class="muted">No completed services recorded.</p>'}</div>`).join('')}</div>`+(rows.length?'':empty('No assets recorded.'));}
function arrivalCards(rows){return rows.map(a=>`<button class="card arrival-card" data-action="arrival-open" data-id="${a.id}" type="button"><div class="eyebrow">${esc(propertyName(a.property_id))}</div><h2>${esc(a.arrival_at.replace('T',' '))}</h2><p class="muted">${esc(a.needs||'No additional notes')}</p><div class="actions"><span class="badge">${a.room_status?.filter(r=>r.ready).length||0}/${a.room_status?.length||0} rooms ready</span><span class="badge">${a.items?.filter(i=>['purchased','stocked'].includes(i.status)).length||0}/${a.items?.length||0} items stocked</span></div></button>`).join('')||empty('No arrivals in this section.');}
function arrivalDetail(a){return btn('Back to arrivals','arrival-back')+`<div class="hero summary"><div class="eyebrow">${esc(propertyName(a.property_id))}</div><h1>Arrival preparation</h1><div class="muted">${esc(a.arrival_at.replace('T',' '))}</div>${badge(a.status)}</div><div class="two"><div class="panel"><h2>Notes</h2><p class="pre">${esc(a.needs||'No additional notes.')}</p></div><div class="panel"><h2>Shopping items</h2>${a.items?.map(i=>`<div class="row ${['purchased','stocked'].includes(i.status)?'item-stocked':''}"><div><strong>${esc(i.name)} · ${esc(i.quantity)}</strong><div class="muted">${esc(i.notes||'')}</div></div>${isStaff()?`<div class="actions"><label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-item="${i.id}" data-item-field="purchased" ${['purchased','stocked'].includes(i.status)?'checked':''}> Purchased</label><label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-item="${i.id}" data-item-field="substitutionNeeded" ${i.substitutionNeeded?'checked':''}> Substitution needed</label><input class="substitution-input" aria-label="What was purchased instead" data-arrival="${a.id}" data-item="${i.id}" data-item-field="substitution" value="${esc(i.substitution||'')}" placeholder="What was purchased instead?"></div>`:badge(i.status)}</div>`).join('')||empty('No shopping items selected.')}</div></div><div class="panel summary"><h2>Rooms</h2>${a.room_status?.map(r=>`<div class="row room-readiness ${r.ready?'room-ready':''}"><strong>${esc(r.name)}</strong>${isStaff()?`<label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-room-key="${esc(r.key)}" data-room-field="ready" ${r.ready?'checked':''}> Ready</label>`:r.ready?badge('ready'):badge('open')}</div>`).join('')||empty('No rooms configured.')}</div><div class="actions summary">${isStaff()&&!['ready','completed','cancelled'].includes(a.status)?btn('Confirm preparation is ready','arrival-ready',a.id,true):''}</div>`;}
function arrivalRows(rows){return rows.map(a=>`<div class="panel"><div class="row"><div><h3>${esc(propertyName(a.property_id))}</h3><div class="muted">Arrival ${esc(a.arrival_at.replace('T',' '))}</div></div>${badge(a.status)}</div><p class="pre">${esc(a.needs||'No additional needs requested.')}</p>${a.room_status?.length?`<h3 class="summary">Room readiness</h3>${a.room_status.map(r=>`<div class="row room-readiness ${r.ready?'room-ready':''}"><div><strong>${esc(r.name)}</strong></div>${isStaff()?`<label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-room-key="${esc(r.key)}" data-room-field="ready" ${r.ready?'checked':''}> Ready</label>`:r.ready?badge('ready'):badge('open')}</div>`).join('')}`:''}${a.items.map(i=>`<div class="row ${i.status==='stocked'?'item-stocked':''}"><div><strong>${esc(i.name)} · ${esc(i.quantity)}</strong><div class="muted">${esc(i.notes)}</div></div>${isStaff()?`<div class="actions"><label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-item="${i.id}" data-item-field="purchased" ${['purchased','stocked'].includes(i.status)?'checked':''}> Purchased</label><label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-item="${i.id}" data-item-field="substitutionNeeded" ${i.substitutionNeeded?'checked':''}> Substitution needed</label><input class="substitution-input" aria-label="What was purchased instead" data-arrival="${a.id}" data-item="${i.id}" data-item-field="substitution" value="${esc(i.substitution||'')}" placeholder="What was purchased instead?"></div>`:badge(i.status)}</div>`).join('')}<div class="actions summary">${isStaff()&&!['ready','completed','cancelled'].includes(a.status)?btn('Confirm preparation is ready','arrival-ready',a.id,true):''}</div></div>`).join('')||empty('No arrivals planned.');}
function residenceView(){const p=data.properties.find(p=>p.id===propertyId);if(!p)return empty('Residence not available.');let tabs=['overview','inspections','shopping','arrivals','services','documents','assets'];if(isStaff())tabs.push('manual','notes');if(data.user.role==='vendor')tabs=['services'];let html=btn('Back to residences','navigate','properties')+`<div class="hero summary"><div class="eyebrow">${esc(p.client_name||'Residence')}</div><h1>${esc(p.name)}</h1><div class="muted">${esc(p.address)}</div><div class="actions">${data.user.role==='admin'?btn('Edit address','edit-property',p.id)+btn('Archive residence','archive-property',p.id):data.user.role==='client'?btn('Plan my arrival','new-arrival',p.id,true):''}</div></div><div class="tabs">${tabs.map(t=>`<button data-action="tab" data-id="${t}" class="${t===tab?'active':''}">${esc(label(t))}</button>`).join('')}</div>`;
 if(tab==='overview')html+=`<div class="two"><div class="panel"><h3>Upcoming work</h3>${workRows(data.work.filter(w=>w.property_id===p.id&&w.status!=='completed'))}</div><div class="panel"><h3>Latest inspections</h3>${inspectionRows(data.inspections.filter(i=>i.property_id===p.id))}</div></div>`;
 if(tab==='inspections')html+=`<div class="panel">${isStaff()?btn('Start inspection','new-inspection',p.id,true):''}${inspectionRows(data.inspections.filter(i=>i.property_id===p.id))}</div>`;
 if(tab==='shopping')html+=`<div class="panel"><div class="head"><h3>Preferred shopping list</h3><div class="actions">${btn('Add item','new-shopping',p.id,true)}${btn('Import CSV / TXT','shopping-import',p.id)}</div></div>${data.shopping.filter(i=>i.property_id===p.id).map(i=>`<div class="row"><div><strong>${esc(i.name)}</strong><div class="muted">${esc(i.category)} · ${esc(i.notes)}</div></div><b>${esc(i.quantity)}</b></div>`).join('')||empty('Add this residence’s preferred groceries and household items.')}${btn('Plan an arrival','new-arrival',p.id)}</div>`;
 if(tab==='arrivals')html+=btn('Plan arrival','new-arrival',p.id,true)+arrivalRows(data.arrivals.filter(a=>a.property_id===p.id));
 if(tab==='services')html+=`<div class="panel">${isStaff()?btn('New work order','new-work',p.id,true):data.user.role==='client'?btn('Request service','new-request',p.id,true):''}${workRows(data.work.filter(w=>w.property_id===p.id))}</div>`;
 if(tab==='documents')html+=`<div class="panel">${isStaff()?btn('Upload document','new-document',p.id,true):''}${fileRows(data.files.filter(f=>f.property_id===p.id&&!f.inspection_id&&!f.work_order_id))}</div>`;
 if(tab==='assets')html+=(isStaff()?btn('Add asset','new-asset',p.id,true):'')+assetRows(data.assets.filter(a=>a.property_id===p.id));
 if(tab==='manual')html+=`<div class="panel"><h3>House manual</h3><p class="muted">Operational procedures for authorized staff. Do not enter gate codes, passwords or alarm credentials in this version.</p><div class="pre">${esc(p.manual||'No procedures recorded yet.')}</div>${btn('Edit manual','edit-manual',p.id)}</div>`;
 if(tab==='notes')html+=`<div class="panel">${btn('Add internal note','new-note',p.id,true)}${data.notes.filter(n=>n.property_id===p.id).map(n=>`<div class="row"><div class="pre">${esc(n.body)}</div><span class="muted">${esc(n.created_at.slice(0,10))}</span></div>`).join('')}</div>`;
 return html;
}
function inspectionView(){const i=data.inspections.find(i=>i.id===activeInspection);if(!i)return empty('Inspection unavailable.');const published=i.status==='published';return head(propertyName(i.property_id),`${i.inspection_date} · ${published?'Published inspection report':'Inspection in progress'}`,btn('Back to reports','navigate','inspections'))+`<div class="panel"><div class="report-title"><div class="actions">${badge(i.status)}${published?`<a class="button primary" href="/api/inspections/${i.id}/pdf">Download PDF report</a>`:''}</div></div>${published?`<h2>Summary</h2><p class="pre">${esc(i.summary)}</p>`:textarea('summary','Inspection summary',i.summary)}<h2>Walkthrough checklist</h2>${i.answers.map(a=>`<div class="inspection-item"><div><div class="eyebrow">${esc(a.section)}</div><strong>${esc(a.label)}</strong></div>${published?badge(a.status):`<select aria-label="Result for ${esc(a.label)}" data-answer="${a.key}">${['unchecked','pass','monitor','attention','na'].map(s=>`<option value="${s}" ${s===a.status?'selected':''}>${s==='na'?'Not applicable':label(s)}</option>`).join('')}</select>`}${published?`<span class="muted">${esc(a.note)}</span>`:`<input aria-label="Notes for ${esc(a.label)}" data-answer-note="${a.key}" value="${esc(a.note)}" placeholder="Reading, observation or N/A reason">`}</div>`).join('')}${published?`<h2>Inspector notes</h2><p class="pre">${esc(i.notes)}</p>`:textarea('notes','Client-visible notes',i.notes)+textarea('internalNotes','Internal notes — not shared in reports',i.internal_notes)}<h2>Photo evidence</h2><div class="photo-grid">${data.files.filter(f=>f.inspection_id===i.id).map(f=>`<a href="/api/files/${f.id}" target="_blank" rel="noopener"><img src="/api/files/${f.id}" alt="${esc(f.name)}"></a>`).join('')}</div>${!published?`<div class="actions">${btn('Add photos','inspection-photo',i.id)}${btn('Save draft','inspection-save',i.id,true)}${data.user.role==='admin'?btn('Complete & publish','inspection-publish',i.id,true):''}</div><p class="muted">Save your draft before leaving. Publishing checks every item and locks the report. Only an administrator can publish.</p>`:''}</div>`;}
function billingView(){const total=data.invoices.reduce((n,i)=>n+i.amount_minor,0),paid=data.invoices.reduce((n,i)=>n+i.paid_minor,0);return head('Billing','Admin-only invoices and payment records.',btn('Create invoice','new-invoice','',true))+`<div class="stats"><div class="stat">Invoiced<b>${money(total)}</b></div><div class="stat">Collected<b>${money(paid)}</b></div><div class="stat">Outstanding<b>${money(total-paid)}</b></div></div><div class="panel table-wrap"><table><thead><tr><th>Invoice</th><th>Client</th><th>Amount</th><th>Balance</th><th>Due</th><th></th></tr></thead><tbody>${data.invoices.map(i=>`<tr><td><b>${esc(i.number)}</b><div class="muted">${esc(i.description)}</div></td><td>${esc(i.client_name)}</td><td>${money(i.amount_minor)}</td><td>${money(i.amount_minor-i.paid_minor)}</td><td>${esc(i.due_date)}</td><td>${i.paid_minor<i.amount_minor?btn('Record payment','new-payment',i.id):badge('paid')}</td></tr>`).join('')}</tbody></table>${!data.invoices.length?empty('No invoices yet.'):''}</div>`;}
function usersView(){return head('Team & access','Each person uses their own login. Invitations expire after 48 hours.',btn('Invite someone','new-invite','',true))+`<div class="panel">${data.users.map(u=>`<div class="row"><div><strong>${esc(u.name)}</strong><div class="muted">${esc(u.email)} · ${esc(u.role)}${!u.active?' · Suspended':''}</div></div><div class="actions">${u.role==='employee'?btn('Assign residence','grant-access',u.id):''}${u.id!==data.user.id&&u.active?btn('Suspend access','suspend-user',u.id):''}</div></div>`).join('')}</div>`;}
function routeView(){return head('Plan your day','Choose due residences in visit order and open road directions.')+`<div class="notice">Map-based clustering and travel-time optimization are not connected yet. This working route handoff uses your chosen order; it does not invent mileage or traffic estimates.</div><div class="panel">${input('origin','Starting address','text','',false)}<h3 class="summary">Residences with open work</h3>${data.properties.filter(p=>data.work.some(w=>w.property_id===p.id&&w.status!=='completed')).map(p=>`<label class="check-row"><input type="checkbox" class="route-stop" value="${p.id}"><span><b>${esc(p.name)}</b><br><span class="muted">${esc(p.address||'Add an address before navigation')}</span></span></label>`).join('')||empty('No open work at your residences.')}${btn('Open Google Maps directions','navigate-route','',true)}</div>`;}

const residenceSelect=selected=>select('propertyId','Residence',option(data.properties,'id','name',selected||propertyId));
function createForm(title,fields,endpoint,extra={},after){dialog(title,fields,'Save',async b=>{const result=await api(endpoint,{...b,...extra});if(after)after(result);toast('Saved.');});}
function wireResidenceForm(){syncRoomProfile();document.querySelectorAll('[name=roomKey],#f-bedrooms,#f-fullBathrooms,#f-halfBathrooms').forEach(el=>el.addEventListener('change',syncRoomProfile));const search=$('f-addressSearch'),suggestions=$('addressSuggestions');if(!search||!suggestions)return;let timer;search.addEventListener('input',()=>{clearTimeout(timer);const q=search.value.trim();if(q.length<3){suggestions.innerHTML='';return;}timer=setTimeout(async()=>{try{const rows=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=5&q='+encodeURIComponent(q),{headers:{Accept:'application/json'}}).then(r=>r.json());suggestions.innerHTML=rows.map((row,i)=>`<button type="button" class="address-suggestion" data-address-index="${i}">${esc(row.display_name)}</button>`).join('');suggestions.querySelectorAll('[data-address-index]').forEach((el,i)=>el.onclick=()=>{const a=rows[i].address||{};$('f-streetAddress').value=[a.house_number,a.road].filter(Boolean).join(' ')||rows[i].display_name;$('f-city').value=a.city||a.town||a.village||'';$('f-state').value=a.state||'';$('f-postalCode').value=a.postcode||'';$('f-country').value=a.country||'United States';search.value=rows[i].display_name;suggestions.innerHTML='';});}catch{suggestions.innerHTML='<span class="muted">Address lookup unavailable; enter the fields manually.</span>'; }},350);});}

async function saveInspection(){const i=data.inspections.find(i=>i.id===activeInspection);const answers=i.answers.map(a=>({...a,status:document.querySelector(`[data-answer="${a.key}"]`).value,note:document.querySelector(`[data-answer-note="${a.key}"]`).value}));const result=await api('inspections/save',{id:i.id,version:i.version,answers,summary:$('f-summary').value,notes:$('f-notes').value,internalNotes:$('f-internalNotes').value});i.version=result.version;i.answers=answers;return i;}
async function jpeg(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPEG, PNG or WebP photo. Convert HEIC photos first.');if(file.size>10*1024*1024)throw Error('Choose a photo smaller than 10 MB.');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.85).split(',')[1];}
function uploadForm(title,prop,inspectionId=null,workId=null){dialog(title,`${prop?'':residenceSelect()}<div class="field full"><label for="upload">${inspectionId||workId?'Photos':'JPEG photo or PDF document'}</label><input id="upload" type="file" accept="${inspectionId||workId?'image/jpeg,image/png,image/webp':'application/pdf,image/jpeg,image/png,image/webp'}" ${inspectionId||workId?'multiple':''} required></div>${!inspectionId&&!workId?select('visibility','Who can see this document?','<option value="internal">Staff only</option><option value="client">Staff and this family</option>'):''}`,'Upload',async(b,form)=>{const files=[...form.querySelector('#upload').files];if(files.length>10)throw Error('Upload at most 10 photos at a time.');for(const file of files){if(file.size>10*1024*1024)throw Error('Maximum size is 10 MB per file.');let base64;if(file.type==='application/pdf'){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let pos=0;pos<bytes.length;pos+=8192)binary+=String.fromCharCode(...bytes.subarray(pos,pos+8192));base64=btoa(binary);}else base64=await jpeg(file);await api('files',{propertyId:prop||b.propertyId,inspectionId,workId,name:file.type==='application/pdf'?file.name:file.name.replace(/\.[^.]+$/,'')+'.jpg',base64,visibility:b.visibility});}toast('Files uploaded.');});}
function parseCsv(text){const rows=[];let row=[],field='',quoted=false;for(let n=0;n<text.length;n++){const c=text[n];if(c==='"'){if(quoted&&text[n+1]==='"'){field+='"';n++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field.trim());field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[n+1]==='\n')n++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('CSV contains an unclosed quotation mark.');row.push(field.trim());if(row.some(Boolean))rows.push(row);return rows;}
async function action(name,key,button){
 if(name==='close'){$('modal').close();return;}
 if(name==='menu'){$('sidebar').classList.toggle('open');return;}
 if(name==='logout'){await api('logout',{});data=null;auth(true);return;}
 if(name==='navigate'){activeClient=null;page=key;search='';activeInspection=null;await load();return;}
 if(name==='arrival-filter'){arrivalFilter=key;activeArrival=null;render();return;}
 if(name==='arrival-open'){activeArrival=key;page='arrivals';render();return;}
 if(name==='arrival-back'){activeArrival=null;render();return;}
 if(name==='property'){propertyId=key;tab=data.user.role==='vendor'?'services':'overview';page='property';render();return;}
 if(name==='tab'){tab=key;render();return;}
 if(name==='inspection'){activeInspection=key;page='inspection';render();return;}
 if(name==='new-client'||name==='edit-client'){const c=name==='edit-client'?data.clients.find(c=>c.id===key):{};familyForm(c);return;}
 if(name==='client-open'){activeClient=key;page='clients';render();return;}
 if(name==='client-back'){activeClient=null;render();return;}
 if(name==='client-member'){createForm('Add family member',input('firstName','First name')+input('lastName','Last name')+input('relationship','Relationship','text','',false)+input('email','Email','email','',false)+input('phone','Phone','text','',false)+contactSelect(),'clients/member',{id:key});return;}
 if(name==='client-residence'){const c=data.clients.find(c=>c.id===key);const p=JSON.parse(c.profile||'{}');createForm('Add residence from family address',input('name','Residence name','text',c.name+' residence')+select('clientId','Client family',option(data.clients,'id','name',c.id))+addressForm(p)+roomProfileForm(),'properties');setTimeout(wireResidenceForm);return;}
 if(name==='new-property'){if(!data.clients.length)throw Error('Add a client family first.');createForm('Add residence',input('name','Residence name')+select('clientId','Client family',option(data.clients))+addressForm()+roomProfileForm(),'properties');setTimeout(wireResidenceForm);return;}
 if(name==='edit-property'){const p=data.properties.find(p=>p.id===key);if(!p)throw Error('Residence unavailable.');createForm('Edit residence profile',input('name','Residence name','text',p.name)+addressForm(p)+roomProfileForm(p),'properties/update',{id:key});setTimeout(wireResidenceForm);return;}
 if(name==='archive-property'){const p=data.properties.find(p=>p.id===key);if(!p)throw Error('Residence unavailable.');if(!confirm(`Archive ${p.name}? Its records will be preserved, but it will leave active residence lists.`))return;await api('properties/archive',{id:key,confirm:true});page='properties';propertyId=null;await load();toast('Residence archived. Its records were preserved.');return;}
 if(name==='restore-property'){if(!confirm('Restore this residence to the active residence lists?'))return;await api('properties/restore',{id:key});await load();toast('Residence restored.');return;}
 if(name==='new-vendor')return createForm('Add vendor company',input('name','Vendor name')+input('trade','Service type')+input('email','Email','email','',false)+input('phone','Phone','text','',false),'vendors');
 if(name==='new-work'||name==='asset-work'){if(!data.properties.length)throw Error('Add or assign a residence first.');const asset=name==='asset-work'?data.assets.find(a=>a.id===key):null;return createForm('Create work order',input('title','Work title')+residenceSelect(asset?.property_id||key)+select('vendorId','Assigned vendor','<option value="">Internal staff</option>'+option(data.vendors))+select('priority','Priority','<option>Normal</option><option>High</option><option>Urgent</option>')+input('dueDate','Due date','date',today(),false)+textarea('description','Work instructions'),'work',asset?{assetId:asset.id}:{});}
 if(name==='new-request'){if(!data.properties.length)throw Error('No residence is assigned to you yet.');return createForm('Request service',residenceSelect(key)+input('title','What do you need?')+textarea('description','Details'),'requests');}
 if(name==='link-request'){const r=data.requests.find(r=>r.id===key),jobs=data.work.filter(w=>w.property_id===r.property_id);if(!jobs.length)throw Error('Create a work order for this residence first.');return createForm('Link request to work',select('workId','Work order',option(jobs,'id','title')),'requests/assign',{id:key});}
 if(name==='new-inspection'){if(!data.properties.length)throw Error('Add or assign a residence first.');return createForm('Start monthly inspection',residenceSelect(key)+input('date','Inspection date','date',today()),'inspections',{},result=>{page='inspection';activeInspection=result.id;});}
 if(name==='inspection-save'){await saveInspection();await load();toast('Inspection draft saved.');return;}
 if(name==='inspection-publish'){await saveInspection();const i=data.inspections.find(i=>i.id===key);await api('inspections/publish',{id:key,version:i.version,idempotencyKey:crypto.randomUUID()});await load();toast('Published. The family can now view and download this report.');return;}
 if(name==='inspection-photo'){await saveInspection();const i=data.inspections.find(i=>i.id===key);return uploadForm('Add inspection photos',i.property_id,key);}
 if(name==='work-photo'){const w=data.work.find(w=>w.id===key);return uploadForm('Add service evidence',w.property_id,null,key);}
 if(name==='work-submit'){const w=data.work.find(w=>w.id===key);return createForm('Submit work for review',textarea('notes','Describe the work completed',w.service_notes),'work/action',{id:key,version:w.version,action:'submit'});}
 if(['work-start','work-accept','work-return'].includes(name)){const w=data.work.find(w=>w.id===key);await api('work/action',{id:key,version:w.version,action:name.slice(5)});await load();toast('Work updated.');return;}
 if(name==='new-asset')return createForm('Add asset',input('name','Asset name')+residenceSelect(key)+input('category','Category','text','',false)+input('model','Model','text','',false)+input('serial','Serial / ID','text','',false)+input('location','Location','text','',false)+input('warranty','Warranty expiry / details','text','',false),'assets');
 if(name==='new-document')return uploadForm('Upload residence document',key||null);
 if(name==='new-shopping')return shoppingForm(key);
 if(name==='shopping-import'){dialog('Import preferred shopping list','<div class="field full"><label for="shoppingFile">CSV or TXT file</label><input type="file" id="shoppingFile" accept=".csv,.txt" required></div><div class="notice field full">Items are appended. CSV headers: name, quantity, category, notes. TXT: one item per line.</div><div id="importPreview" class="field full"></div>','Import items',async(_,form)=>{const rows=form._rows;if(!rows?.length)throw Error('Select a valid shopping list.');for(const item of rows)await api('shopping',{propertyId:key,...item});toast(rows.length+' items imported.');});$('shoppingFile').onchange=async e=>{try{const file=e.target.files[0];if(file.size>1024*1024)throw Error('Maximum import size is 1 MB.');let rows=parseCsv((await file.text()).replace(/^\uFEFF/,''));const header=rows[0]?.map(x=>x.toLowerCase());let mapping=null;if(header?.some(x=>['name','item','product'].includes(x)))mapping=rows.shift().map(x=>x.toLowerCase());if(rows.length>500)throw Error('Maximum 500 items.');const items=rows.map(r=>{const take=(keys,index)=>mapping?r[mapping.findIndex(h=>keys.includes(h))]||'':r[index]||'';const item={name:take(['name','item','product'],0),quantity:take(['quantity','qty'],1)||'1',category:take(['category'],2),notes:take(['notes','note'],3)};if(!item.name)throw Error('Every row needs an item name.');return item;});$('actionForm')._rows=items;$('importPreview').innerHTML=`<b>${items.length} items to add</b><p class="muted">${items.slice(0,8).map(i=>esc(i.name)+' × '+esc(i.quantity)).join('<br>')}</p>`;}catch(error){$('formError').hidden=false;$('formError').textContent=error.message;}};return;}
 if(name==='new-arrival'){if(!data.properties.length)throw Error('Add or assign a residence first.');const p=key||propertyId||data.properties[0].id;dialog('Prepare residence for arrival',residenceSelect(p)+input('arrivalAt','Arrival date and time','datetime-local')+textarea('needs','Additional preparation needs')+'<div class="field full" id="arrivalSelections"></div>','Submit arrival',async(b,form)=>{b.itemIds=[...form.querySelectorAll('[name="itemId"]:checked')].map(el=>el.value);await api('arrivals',b);toast('Arrival preparation requested.');});const fill=()=>{$('arrivalSelections').innerHTML='<b>Select preferred groceries</b>'+data.shopping.filter(i=>i.property_id===$('f-propertyId').value).map(i=>`<label class="check-row"><input type="checkbox" name="itemId" value="${i.id}"><span>${esc(i.name)} · ${esc(i.quantity)}</span></label>`).join('');};$('f-propertyId').onchange=fill;fill();return;}
 if(name==='arrival-ready'){const a=data.arrivals.find(a=>a.id===key);dialog('Confirm residence is ready',`<p class="field full pre">${esc(a.needs||'No additional needs were requested.')}</p><label class="check-row field full"><input name="confirmNeeds" type="checkbox" required><span>All requested preparation tasks are complete.</span></label>`,'Mark ready',async()=>{await api('arrivals/update',{id:key,version:a.version,status:'ready',confirmNeeds:true});toast('Residence marked ready.');});return;}
 if(name==='new-maintenance')return createForm('Add maintenance schedule',residenceSelect()+input('title','Maintenance item')+select('frequency','Frequency','<option>Weekly</option><option>Monthly</option><option>Quarterly</option><option>Annual</option>')+input('nextDue','Next due date','date',today()),'maintenance');
 if(name==='generate-maintenance'){await api('maintenance/generate',{id:key});await load();toast('Due work is available in Work orders.');return;}
 if(name==='run-maintenance'){const until=new Date();until.setDate(until.getDate()+30);const result=await api('maintenance/run-due',{until:until.toISOString().slice(0,10)});await load();toast(`${result.generatedCount} due maintenance visit${result.generatedCount===1?'':'s'} created.`);return;}
 if(name==='new-invoice'){if(!data.clients.length)throw Error('Add a client family first.');return dialog('Create invoice',select('clientId','Client family',option(data.clients))+input('number','Invoice number')+input('amount','Amount (USD)','number')+input('dueDate','Due date','date',today())+textarea('description','Services billed'),'Create invoice',async b=>{b.amountMinor=Math.round(Number(b.amount)*100);await api('invoices',b);});}
 if(name==='new-payment'){const i=data.invoices.find(i=>i.id===key);return dialog('Record payment',input('amount','Amount received (USD)','number',((i.amount_minor-i.paid_minor)/100).toFixed(2))+input('reference','Payment method / reference','text','',false),'Record payment',async b=>{await api('payments',{invoiceId:key,amountMinor:Math.round(Number(b.amount)*100),reference:b.reference});});}
 if(name==='new-invite'){dialog('Invite an account',input('email','Email','email')+select('role','Role','<option value="employee">Employee</option><option value="client">Client</option><option value="vendor">Vendor</option><option value="admin">Administrator</option>')+select('clientId','Family (client accounts only)','<option value="">Select family</option>'+option(data.clients))+select('vendorId','Company (vendor accounts only)','<option value="">Select vendor</option>'+option(data.vendors)),'Create invitation',async b=>{const result=await api('invitations',b);setTimeout(()=>{const link=location.origin+result.invitePath;$('modalBody').innerHTML=`<h2>Invitation created</h2><p class="muted">Share this link directly with ${esc(b.email)}. It expires in 48 hours and can be used once. No email has been sent.</p><input aria-label="Invitation link" readonly value="${esc(link)}"><p class="muted">While this app runs only on your computer, this link works only there. A hosted address is needed for other people to connect.</p>${btn('Close','close')}`;$('modal').showModal();},50);});return;}
 if(name==='grant-access')return createForm('Assign employee residence',residenceSelect(),'access',{userId:key});
 if(name==='suspend-user'){dialog('Suspend this account?','<p class="field full">Existing sessions will stop working. This does not delete their records.</p>','Suspend account',()=>api('users/suspend',{userId:key}));return;}
 if(name==='new-note')return createForm('Add internal note',textarea('body','Note'),'notes',{propertyId:key});
 if(name==='edit-manual'){const p=data.properties.find(p=>p.id===key);return createForm('Edit house manual',textarea('manual','Staff operating procedures',p.manual),'manual',{propertyId:key});}
 if(name==='read-notification'){await api('notifications/read',{id:key});await load();return;}
 if(name==='navigate-route'){const stops=[...document.querySelectorAll('.route-stop:checked')].map(el=>data.properties.find(p=>p.id===el.value));if(!stops.length)throw Error('Select at least one residence.');if(stops.some(p=>!p.address))throw Error('Add full addresses before navigation.');if(stops.length>4)throw Error('Use up to four residences per navigation handoff.');const params=new URLSearchParams({api:'1',destination:stops.at(-1).address,travelmode:'driving'});if($('f-origin').value)params.set('origin',$('f-origin').value);if(stops.length>1)params.set('waypoints',stops.slice(0,-1).map(p=>p.address).join('|'));window.open('https://www.google.com/maps/dir/?'+params,'_blank','noopener');return;}
}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();button.disabled=true;try{await action(button.dataset.action,button.dataset.id,button);}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.addEventListener('change',async event=>{const el=event.target;if(!el.dataset.arrival)return;const a=data.arrivals.find(a=>a.id===el.dataset.arrival);try{const payload={id:a.id,version:a.version};if(el.dataset.item){const field=el.dataset.itemField;if(field==='substitutionNeeded')Object.assign(payload,{itemId:el.dataset.item,substitutionNeeded:el.checked,substitution:el.closest('.actions')?.querySelector('[data-item-field=\"substitution\"]')?.value||''});else if(field==='substitution')Object.assign(payload,{itemId:el.dataset.item,substitutionNeeded:el.closest('.actions')?.querySelector('[data-item-field=\"substitutionNeeded\"]')?.checked||false,substitution:el.value});else Object.assign(payload,{itemId:el.dataset.item,itemStatus:el.checked?'purchased':'requested'});}if(el.dataset.roomKey)Object.assign(payload,{roomKey:el.dataset.roomKey,roomReady:el.checked});await api('arrivals/update',payload);await load();toast(el.dataset.roomKey?'Room readiness saved.':el.dataset.itemField==='substitutionNeeded'||el.dataset.itemField==='substitution'?'Substitution details saved.':'Purchase status saved.');}catch(error){toast(error.message);await load();}});
async function boot(){try{const status=await api('status');const invitation=new URLSearchParams(location.search).get('invite');if(status.user&&!invitation)await load();else auth(status.configured,invitation);}catch(error){$('app').innerHTML=`<div class="loading"><h1>EstateOS could not connect</h1><p>${esc(error.message)}</p><p>Keep the EstateOS server running, then refresh this page.</p></div>`;}}
boot();
window.addEventListener('focus',()=>{if(data&&page!=='inspection'&&!$('modal').open)load().catch(error=>toast(error.message));});
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 Promise.resolve(document.modelContext.registerTool({name:'open_estateos_inspection',title:'Open inspection report',description:'Open an inspection already accessible to the signed-in account. Does not publish or modify records.',inputSchema:{type:'object',properties:{inspectionId:{type:'string'}},required:['inspectionId'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(!input||typeof input.inspectionId!=='string'||Object.keys(input).length!==1)throw Error('Provide an inspectionId.');await load();const report=data.inspections.find(i=>i.id===input.inspectionId);if(!report)throw Error('Inspection unavailable to this account.');activeInspection=report.id;page='inspection';render();return {id:report.id,status:report.status};}},{signal:lifecycle.signal})).catch(()=>{});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}


function contactSelect(value='No preference'){return select('preferredContact','Preferred contact method',['No preference','Email','Phone call','Text message'].map(v=>'<option '+(v===value?'selected':'')+'>'+v+'</option>').join(''));}
function familyForm(c={}){const p=JSON.parse(c.profile||'{}');const fields=input('firstName','First name','text',p.firstName||'')+input('lastName','Last name','text',p.lastName||'')+input('name','Family name','text',c.name||'')+input('email','Email','email',c.email||'',false)+input('phone','Phone','text',c.phone||'',false)+contactSelect(p.preferredContact)+addressForm(p);createForm(c.id?'Edit family':'Add client family',fields,c.id?'clients/update':'clients',c.id?{id:c.id}:{},result=>{activeClient=result.id;page='clients';});let custom=!!c.id;$('f-name').oninput=()=>{custom=!!$('f-name').value;};$('f-lastName').oninput=()=>{if(!custom)$('f-name').value=$('f-lastName').value;};document.querySelectorAll('.address-fields input').forEach(el=>el.required=false);wireResidenceForm();}
function clientView(c){const p=JSON.parse(c.profile||'{}');const contact=x=>esc([x.email,x.phone,x.preferredContact].filter(Boolean).join(' · '));return head(c.name+' family','Client family profile',btn('Back to families','client-back'))+'<div class="panel"><div class="head"><h2>Primary contact</h2>'+btn('Edit family','edit-client',c.id)+'</div><strong>'+esc([p.firstName,p.lastName].filter(Boolean).join(' ')||c.name)+'</strong><p class="muted">'+contact({...c,preferredContact:p.preferredContact})+'</p><h3>Address</h3><p>'+esc([p.street_address,p.address_line2,p.city,p.state,p.postal_code,p.country].filter(Boolean).join(', ')||'No address entered')+'</p>'+btn('Add this address as a residence','client-residence',c.id)+'</div><div class="panel summary"><div class="head"><h2>Family members</h2>'+btn('Add family member','client-member',c.id,true)+'</div>'+((p.members||[]).map(m=>'<div class="row"><div><strong>'+esc(m.firstName+' '+m.lastName)+'</strong><div class="muted">'+esc(m.relationship)+'<br>'+contact(m)+'</div></div></div>').join('')||empty('No additional family members yet.'))+'</div><div class="panel summary"><h2>Residences</h2>'+ (data.properties.filter(r=>r.client_id===c.id).map(r=>'<div class="row"><strong>'+esc(r.name)+'</strong>'+btn('View residence','property',r.id)+'</div>').join('')||empty('No residences yet.'))+'</div>';}
